CREATE DATABASE IF NOT EXISTS bizmaster CHARACTER SET utf8mb4;
USE bizmaster;
CREATE TABLE users(id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, email VARCHAR(160) NOT NULL UNIQUE,
  password_hash VARCHAR(100) NOT NULL, role ENUM('admin','empleado','cliente','contador') NOT NULL DEFAULT 'empleado', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE contacts(id INT AUTO_INCREMENT PRIMARY KEY, type ENUM('cliente','proveedor') NOT NULL, name VARCHAR(160) NOT NULL,
  nit VARCHAR(30), email VARCHAR(160), phone VARCHAR(30), category VARCHAR(60), notes TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE products(id INT AUTO_INCREMENT PRIMARY KEY, sku VARCHAR(40) NOT NULL UNIQUE, barcode VARCHAR(60), name VARCHAR(160) NOT NULL,
  price DECIMAL(12,2) NOT NULL, stock INT NOT NULL DEFAULT 0, min_stock INT NOT NULL DEFAULT 5);
CREATE TABLE stock_moves(id INT AUTO_INCREMENT PRIMARY KEY, product_id INT NOT NULL, qty INT NOT NULL, reason VARCHAR(60), user_id INT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY(product_id) REFERENCES products(id));
CREATE TABLE invoices(id INT AUTO_INCREMENT PRIMARY KEY, number VARCHAR(20), contact_id INT NOT NULL, user_id INT, subtotal DECIMAL(12,2), iva DECIMAL(12,2), total DECIMAL(12,2),
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(contact_id) REFERENCES contacts(id));
CREATE TABLE invoice_items(id INT AUTO_INCREMENT PRIMARY KEY, invoice_id INT NOT NULL, product_id INT NOT NULL, qty INT NOT NULL, unit_price DECIMAL(12,2) NOT NULL,
  FOREIGN KEY(invoice_id) REFERENCES invoices(id), FOREIGN KEY(product_id) REFERENCES products(id));
